// Praeneste's west side gets content; Capua «Два кольца» shows how to break in and how many reinforcements come;
// a fourth Capua map mixes «Аппиева ось» (river in front, three crossings, villa and gladiator school) with «Два кольца» (two walls, gatehouses, keep).
const fs = require('fs');
const edit = (file, fn) => { let t = fs.readFileSync(file, 'utf8'); const rep = (a, b) => { if (!t.includes(a)) { console.error('MISS', file, a.slice(0, 60)); process.exit(1); } t = t.replace(a, () => b); }; fn(rep); fs.writeFileSync(file, t); };

edit('cities.js', rep => {
  rep("  for (const [x, y] of [[200, 1300], [120, 1200]]) olive(g, x, y, 1);", String.raw`  // the west side: a limestone quarry under the hill, charcoal burners in a pine wood, a farm with a vineyard below the swamp
  quarry(g, 110, 560); point(g, 0, 0, 0);
  grove(g, 90, 760, 70, 60, 9, 11); for (const [dx, dy] of [[150, 800], [40, 860]]) pine(g, dx, dy, 0.9);
  rr(g, 150, 690, 34, 22, 6); fo(g, '#6a4a30', 2); for (const [sx, sy] of [[167, 680], [172, 666], [165, 652]]) { g.beginPath(); g.arc(sx, sy, 6, 0, 7); g.fillStyle = 'rgba(230,230,225,.75)'; g.fill(); }
  vineyard(g, 40, 1240, 180, 100); etrHouse(g, 270, 1300); etrHouse(g, 230, 1250); olive(g, 300, 1220, 1); olive(g, 60, 1380, 0.9);
  path(g, [[200, 1240], [230, 1100], [200, 940], [150, 760], [120, 600]], 18);`);
  rep("['e_arc', 300, 440], ['e_arc', 560, 440]", "['e_arc', 300, 440], ['e_arc', 560, 440], ['e_inf', 150, 620, 3]");
});
// the dummy point call above draws nothing (radius 0); remove it cleanly
edit('cities.js', rep => rep("quarry(g, 110, 560); point(g, 0, 0, 0);", "quarry(g, 110, 560);"));

edit('capua.js', rep => {
  // «Два кольца»: a breach in the old west wall, the inner gate, and the reinforcement counter on the map
  rep("  portcullis(g, 240, 836, 0.7); portcullis(g, 660, 836, 0.7); point(g, 240, 880, 70); point(g, 660, 880, 70);",
      "  portcullis(g, 240, 836, 0.7); portcullis(g, 660, 836, 0.7); point(g, 240, 880, 70); point(g, 660, 880, 70);\n  g.fillStyle = '#8ad25c'; g.fillRect(64, 480, 34, 90); rubble(g, 80, 530, 0); g.beginPath(); g.arc(80, 480, 14, 0, 7); fo(g, '#f09a24', 2.4); g.font = '15px sans-serif'; g.textAlign = 'center'; g.fillText('⛏', 80, 486);\n  sign(g, 640, 210, 'подкрепления: 1 отряд / 75 с · всего 4', '#9ec1ff');");
  rep("num(g, 70, 1300, 6);", "num(g, 70, 1300, 6); num(g, 40, 470, 7);");
  rep("const MAPS3 = [['ca', capA, 51], ['cb', capB, 53], ['cc', capC, 57]];", String.raw`// ---------------------------------------------------------------- 4. «Ось и два кольца» — the mix of 1 and 2
function capD(g, r) {
  grass(g, 0, 0, WW, WH, '#8ad25c', r);
  stream(g, [[0, 80], [300, 100], [600, 70], [900, 90]], 60, r); stoneBridge(g, 450, 40, 124, 34); arrowsIn(g, 450, 170, Math.PI / 2);
  sign(g, 660, 160, 'подкрепления: 1 / 75 с · всего 4', '#9ec1ff');
  vineRows(g, 40, 1060, 220, 140); vineRows(g, 640, 1180, 220, 120);
  roads(g, [[[[450, 1500], [450, 1220], [450, 1000], [450, 900], [450, 820]], 38], [[[450, 1220], [190, 1110], [170, 960], [240, 820]], 26], [[[450, 1220], [730, 1100], [730, 960], [660, 820]], 26], [[[240, 760], [240, 690], [450, 640], [660, 690], [660, 760]], 30, true], [[[450, 640], [450, 560], [450, 440]], 36, true], [[[450, 300], [450, 130]], 32, true]], r);
  // the Volturnus in front of the city: a ford, the main bridge, a narrow footbridge
  stream(g, [[0, 920], [300, 900], [600, 910], [900, 890]], 66, r);
  for (const [x, y, s] of [[160, 900, 1], [182, 918, 1.1], [150, 930, 0.9], [190, 892, 0.8]]) stone(g, x, y, s);
  stoneBridge(g, 450, 856, 956, 40); stoneBridge(g, 730, 846, 934, 24);
  // act 1: the outer wall along the river — the arch in the middle is the strongest gate, the two gatehouses are the capture points
  wall(g, [[80, 780], [80, 240], [820, 240], [820, 780], [700, 780], [620, 780], [530, 780], [370, 780], [280, 780], [200, 780], [80, 780]], '#d8ccb4', [4, 6, 8]);
  arch(g, 450, 796); portcullis(g, 240, 794, 0.66); portcullis(g, 660, 794, 0.66); point(g, 240, 836, 66); point(g, 660, 836, 66);
  // act 2: the inner ring and the keep
  wall(g, [[290, 560], [290, 330], [610, 330], [610, 560], [520, 560], [380, 560], [290, 560]], '#e2d6bc', [4]);
  keep(g, 450, 470); point(g, 450, 492, 84);
  for (const [x, y] of [[160, 360], [740, 360], [160, 600], [740, 600], [180, 700], [720, 700]]) house(g, x, y);
  villa(g, 160, 1130); arena(g, 740, 1060, 80, 50, r); ludus(g, 740, 980);
  camp(g, 450, 1410);
  foe(g, [['e_inf', 450, 840, 5], ['hoplite', 450, 720, 6], ['e_arc', 360, 780, 2], ['e_arc', 540, 780, 2], ['e_inf', 240, 740, 4], ['e_inf', 660, 740, 4], ['e_arc', 110, 780, 2], ['e_arc', 790, 780, 2], ['ambush', 120, 1100, 4], ['e_cav', 620, 1000, 4], ['hoplite', 450, 600, 6], ['e_arc', 330, 380], ['e_arc', 570, 380], ['e_inf', 450, 380, 5], ['e_cav', 450, 200, 4]]);
  ours(g, 450, 1370);
  sign(g, 450, 1482, '↓ из Пренесте', '#ff8a6a'); sign(g, 300, 960, 'Вольтурн', '#9ec1ff'); sign(g, 450, 880, 'Акт 1: внешняя стена', '#f2c14a'); sign(g, 450, 310, 'Акт 2: цитадель', '#f2c14a');
  num(g, 450, 1310, 1); num(g, 90, 1200, 2); num(g, 840, 1120, 2); num(g, 120, 870, 3); num(g, 520, 900, 3); num(g, 790, 870, 3); num(g, 520, 740, 4); num(g, 170, 830, 5); num(g, 730, 830, 5); num(g, 560, 440, 6);
}
const MAPS3 = [['ca', capA, 51], ['cb', capB, 53], ['cc', capC, 57], ['cd', capD, 59]];`);
  rep("  ${card('cb', '2. Два кольца', 'идея геймдизайнера · осада в два акта; Вольтурн течёт за городом, как в истории', [", "  ${card('cb', '2. Два кольца', 'идея геймдизайнера · осада в два акта; Вольтурн течёт за городом, как в истории', ['<b>Как пробиться внутрь — три пути.</b> Западные или восточные ворота: встать у надвратной башни (точка захвата), инженеры поднимают решётку за 8 с под стрелами со стен. Или пролом в старой западной стене (⛏, 7): инженеры разбирают завал за 10 с, там стрелять некому — но путь длинный. Внутреннее кольцо открыто аркой, её держит фаланга; войдя с двух сторон, бьёте ей во фланг.', '<b>Подкрепления:</b> по мосту за городом каждые 75 с приходит 1 отряд, всего не больше 4. Поток прекращается, как только вы держите обе надвратные башни — город отрезан. Счётчик над картой: «Подкрепления 2/4 · через 0:40».', ");
  rep("  <p><b>Рекомендации команды:</b>", "  ${card('cd', '4. Ось и два кольца — смесь 1 и 2', 'по вашей просьбе: что взяли из первого и из второго', ['<b>Из первого:</b> всё на одной оси — лагерь, главный мост, арка, донжон; Вольтурн перед городом с тремя переправами (брод, мост, мостик); вилла и школа гладиаторов на нашем берегу (2) — побочные цели.', '<b>Переправы (3)</b>: брод на западе — длинно, мост — коротко и прямо к арке, мостик на востоке — к восточной башне.', '<b>Арка (4)</b> — самые сильные ворота: фаланга и лучники на стене. Её можно не штурмовать.', '<b>Из второго:</b> две надвратные башни (5) — точки захвата, решётки поднимают инженеры; взяв обе, вы отрезаете подкрепления (1 отряд / 75 с, всего 4) и заходите в город с двух сторон.', '<b>Акт 2 — цитадель (6)</b>: внутреннее кольцо, донжон — финал; при входе гарнизон выходит в контратаку.'])}\n  <p><b>Рекомендации команды:</b>");
});
console.log('ok');
